// Number families
const famRows = [[r`7`, V('7')], [r`0`, V('0')], [r`-\dfrac{12}{4}`, V(r`-\dfrac{12}{4}`)], [r`\dfrac{5}{8}`, V(r`\dfrac{5}{8}`)], [r`0.\overline{3}`, rat(...fromRecurring(0, '', '3'))], [r`\sqrt{20}`, V(r`\sqrt{20}`)], [r`\sqrt{\dfrac{81}{4}}`, V(r`\sqrt{\dfrac{81}{4}}`)]];
const famCells = famRows.map(([t, x]) => { const n = isInt(x) && x.part()[0] > 0, w = isInt(x) && x.part()[0] >= 0; return [d(t), yn(n), yn(w), yn(isInt(x)), yn(x.rational), yn(!x.rational)]; });
must(famCells[0].slice(1).join() === 'yes,yes,yes,yes,no' && famCells[1].slice(1).join() === 'no,yes,yes,yes,no' && famCells[2].slice(1).join() === 'no,no,yes,yes,no' && famCells[3].slice(1).join() === 'no,no,no,yes,no' && famCells[4].slice(1).join() === 'no,no,no,yes,no' && famCells[5].slice(1).join() === 'no,no,no,no,yes' && famCells[6].slice(1).join() === 'no,no,no,yes,no', 'family table values');
const famTable = table(['Number', 'Natural', 'Whole', 'Integer', 'Rational', 'Irrational'], famCells, 'Table classifying seven numbers. Seven is natural, whole, integer and rational. Zero is whole, integer and rational but not natural. Minus twelve over four equals minus three, an integer and rational. Five eighths and zero point three recurring are rational but not integers. Root twenty is irrational. Root of eighty one over four equals nine over two, which is rational.', 'Every row is checked: a number is irrational exactly when it is not rational.');

// Fractions and their decimals
const decPairs = [[7, 16], [9, 20], [4, 11], [11, 30], [2, 7], [5, 12]];
const decShow = ([n, dd]) => { const e = expansion(n, dd); const s = e.rep ? `0.${e.pre}${e.rep}${e.rep}${e.rep}\\ldots` : `0.${e.pre}`; return s; };
const decRows = decPairs.map(([n, dd]) => { const e = expansion(n, dd); must(terminates(n, dd) === (e.rep === ''), `terminates ${n}/${dd}`); return [d(`\\dfrac{${n}}{${dd}}`), d(decShow([n, dd])), e.rep ? `recurring, block ${e.rep}` : 'terminating', d(factorTex(dd))]; });
must(decRows.map((x) => x[2].split(',')[0]).join() === 'terminating,terminating,recurring,recurring,recurring,recurring' && expansion(7, 16).pre === '4375' && expansion(4, 11).rep === '36' && expansion(11, 30).pre === '3' && expansion(11, 30).rep === '6' && expansion(2, 7).rep === '285714' && expansion(5, 12).pre === '41' && expansion(5, 12).rep === '6', 'decimal table');
const decTable = table(['Fraction', 'Decimal', 'Kind', 'Denominator'], decRows, 'Table of six fractions and their decimals. Seven sixteenths is zero point four three seven five, terminating; nine twentieths is zero point four five, terminating. Four elevenths, eleven thirtieths, two sevenths and five twelfths recur. Only denominators with the prime factors two and five terminate.', 'A fraction in lowest terms terminates only when its denominator is $2^a \\times 5^b$.');

// Recurring decimals: worked examples
const f72 = fromRecurring(0, '', '72');
must(f72[0] === 8 && f72[1] === 11 && expansion(8, 11).rep === '72' && 100 * 1 - 1 === 99 && 72 / 99 === 8 / 11, 'ex1 0.(72)');
const ex1Tab = table(['Step', 'Working'], [['Name it', d(r`x = 0.\overline{72}`)], ['Two digits repeat: multiply by $100$', d(r`100x = 72.\overline{72}`)], ['Subtract', d(r`100x - x = 72, \text{ so } 99x = 72`)], ['Solve and reduce', d(r`x = \dfrac{72}{99} = \dfrac{8}{11}`)]], 'Table of four steps to convert zero point seven two recurring to a fraction: name it x; multiply by one hundred; subtract to get ninety nine x equals seventy two; then x equals seventy two over ninety nine, which is eight elevenths.', 'Multiply by $10^k$, where $k$ digits repeat, and subtract.');
const f256 = fromRecurring(2, '5', '6');
must(f256[0] === 77 && f256[1] === 30 && expansion(77, 30).int === 2 && expansion(77, 30).pre === '5' && expansion(77, 30).rep === '6' && 256 - 25 === 231 && 231 / 90 === 77 / 30, 'ex2 2.5(6)');
const ex2Tab = table(['Step', 'Working'], [['Name it', d(r`x = 2.5\overline{6}`)], ['Move the point past the non-repeating digit', d(r`10x = 25.\overline{6}`)], ['Move it past one repeating block as well', d(r`100x = 256.\overline{6}`)], ['Subtract', d(r`100x - 10x = 231, \text{ so } 90x = 231`)], ['Reduce', d(r`x = \dfrac{231}{90} = \dfrac{77}{30}`)]], 'Table of five steps to convert two point five six recurring: ten x equals twenty five point six recurring; one hundred x equals two hundred fifty six point six recurring; subtracting gives ninety x equals two hundred thirty one; so x is seventy seven thirtieths.', 'Two multipliers, $10x$ and $100x$, line up the repeating parts.');

// Irrational numbers
const irrRows = [[r`\sqrt{2}`, sq(2)], [r`\sqrt{3}`, sq(3)], [r`\sqrt{5}`, sq(5)]];
must(irrRows.every(([, x]) => !x.rational), 'irr rows');
const irrTable = table(['Number', 'Decimal (first digits)', 'Why it is not rational'], [...irrRows.map(([t, x]) => [d(t), d(`${dec(x, 7)}\\ldots`), 'no block repeats and it never stops (proved by contradiction)']), [d(r`0.1010010001\ldots`), 'one more 0 each time', 'the gaps keep growing, so no block repeats']], 'Table of irrational numbers: root two is one point four one four two one three six, root three is one point seven three two zero five zero eight, root five is two point two three six zero six eight, and a pattern decimal whose zeros keep increasing. None repeats and none stops.', 'An irrational number has a non-terminating, non-recurring decimal.');
must(dec(sq(2), 7) === '1.4142136' && dec(sq(3), 7) === '1.7320508' && dec(sq(5), 7) === '2.2360680', 'irr decimals');
const decFlow = flow('TB', [['a', 'Look at the decimal expansion'], ['b', 'It stops: terminating'], ['c', 'A block repeats: recurring'], ['d', 'It never stops and never repeats'], ['e', 'Rational: it equals $\\dfrac{p}{q}$'], ['f', 'Irrational']], [['a', 'b'], ['a', 'c'], ['a', 'd'], ['b', 'e'], ['c', 'e'], ['d', 'f']], 'Flow chart: look at the decimal expansion. If it stops or a block repeats, the number is rational and equals p over q. If it neither stops nor repeats, the number is irrational.', 'Terminating or recurring means rational; neither means irrational.');

// Closure
const clRows = [['rational + rational', r`\dfrac{1}{2} + \dfrac{1}{3}`], ['rational + irrational', r`3 + \sqrt{2}`], ['irrational + irrational', r`\sqrt{2} + (3 - \sqrt{2})`], ['rational × irrational', r`\dfrac{3}{4} \times \sqrt{2}`], ['irrational × irrational', r`\sqrt{2} \times \sqrt{8}`], ['irrational × irrational', r`\sqrt{3} \times \sqrt{5}`]];
