must(clVals.map(kind).join() === 'rational,irrational,rational,irrational,rational,irrational' && vt(clRows[0][1]) === '\\dfrac{5}{6}' && clVals[2].eq(rat(3)) && clVals[4].eq(rat(4)), 'closure rows');
const closeTable = table(['Operation', 'Example', 'Value', 'Result'], clRows.map(([k, e], i) => [k, d(e), d(tex(clVals[i])), kind(clVals[i])]), 'Table of six examples. Rational plus rational is rational. Rational plus irrational, three plus root two, is irrational. Two irrationals can add to a rational: root two plus three minus root two is three. Rational times irrational is irrational. Two irrationals can multiply to a rational, root two times root eight is four, or to an irrational, root three times root five.', 'The sum or product of two irrational numbers may be rational or irrational.');

// Proof visuals
const proofFlow = flow('TB', [['a', 'Assume $\\sqrt{2} = \\dfrac{p}{q}$ in lowest terms'], ['b', 'Square: $p^2 = 2q^2$'], ['c', '$p^2$ is even, so $p$ is even'], ['d', 'Put $p = 2k$: $q^2 = 2k^2$'], ['e', '$q$ is even too'], ['f', '$p$ and $q$ share the factor $2$: contradiction'], ['g', 'So $\\sqrt{2}$ is irrational']], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'e'], ['e', 'f'], ['f', 'g']], 'Flow chart of the proof that root two is irrational: assume root two is p over q in lowest terms; square to get p squared equals two q squared; p is even; put p equal to two k, so q squared is two k squared; q is even too; p and q share the factor two, a contradiction; so root two is irrational.', 'Seven steps: assume, square, parity of $p$, parity of $q$, contradiction, conclude.');
const parRows = [1, 2, 3, 4, 5, 6, 7, 8].map((n) => [d(String(n)), d(String(n * n)), n % 2 ? 'odd' : 'even', n * n % 2 ? 'odd' : 'even']);
