const parTable = table(['$n$', '$n^2$', '$n$ is', '$n^2$ is'], parRows, 'Table for n from one to eight: n squared is odd exactly when n is odd, and even exactly when n is even. For example three squared is nine, odd, and four squared is sixteen, even.', '$n^2$ has the same parity as $n$, so $p^2$ even forces $p$ even.');
const m3Rows = [6, 7, 8, 9, 10, 11].map((p) => [d(String(p)), d(String(p % 3)), d(String(p * p)), d(String((p * p) % 3))]);
must([6, 7, 8, 9, 10, 11].every((p) => (p * p % 3 === 0) === (p % 3 === 0)), 'mod 3 rows');
const m3Table = table(['$p$', '$p$ leaves remainder', '$p^2$', '$p^2$ leaves remainder'], m3Rows, 'Table for p from six to eleven. When p is divisible by three, p squared is divisible by three. When p leaves remainder one or two, p squared leaves remainder one. So three divides p squared only if three divides p.', '$3 \\mid p^2$ exactly when $3 \\mid p$: this drives the proof for $\\sqrt{3}$.');
