// Summary table 1
const sum1 = table(['Idea', 'Key fact'], [['Rational', d(r`\dfrac{p}{q}`) + ', terminating or recurring decimal'], ['Irrational', 'non-terminating, non-recurring decimal'], ['Recurring to fraction', 'multiply by $10^k$ and subtract'], ['Proof by contradiction', 'assume, deduce, contradict, conclude'], ['Number line', 'rationals by division; roots by right triangles']], 'Summary table for part one: rational numbers are p over q with terminating or recurring decimals; irrational numbers have non-terminating, non-recurring decimals; recurring decimals are converted by multiplying by a power of ten and subtracting; proofs by contradiction assume, deduce, contradict and conclude; roots are marked with right triangles.', 'Part 1 on one card.');

// Deck 2 visuals
const surdRows = [[r`\sqrt{27}`, 27], [r`\sqrt{49}`, 49], [r`\sqrt{\dfrac{16}{25}}`, null, V(r`\sqrt{\dfrac{16}{25}}`)], [r`\sqrt{0.09}`, null, V(r`\sqrt{0.09}`)], [r`\sqrt{45}`, 45]];
