must(surdCells.map((c) => c[2].slice(0, 2)).join() === 'ye,no,no,no,ye' && tex(sq(27)) === '3\\sqrt{3}' && tex(V(r`\sqrt{0.09}`)) === '\\dfrac{3}{10}' && tex(sq(45)) === '3\\sqrt{5}', 'surd cells');
surdCells[3][1] = d('0.3'); must(V('0.3').eq(V(r`\sqrt{0.09}`)), '0.3');
