const simpRows = [72, 98, 150, 245, 396].map((n) => { const [s, c] = split(n); must(s * s * c === n && !V(`\\sqrt{${n}}`).rational, `split ${n}`); chain([`\\sqrt{${n}} = \\sqrt{${s * s} \\times ${c}} = ${s}\\sqrt{${c}}`]); return [d(`\\sqrt{${n}}`), d(`\\sqrt{${s * s} \\times ${c}}`), d(`${s}\\sqrt{${c}}`)]; });
must(simpRows.map((x) => x[2]).join() === '$6\\sqrt{2}$,$7\\sqrt{2}$,$5\\sqrt{6}$,$7\\sqrt{5}$,$6\\sqrt{11}$', 'simp rows');
const simpTable = table(['Surd', 'Take out the largest square', 'Simplest form'], simpRows, 'Table of five simplifications. Root seventy two is root thirty six times two, six root two. Root ninety eight is seven root two. Root one hundred fifty is five root six. Root two hundred forty five is seven root five. Root three hundred ninety six is six root eleven.', 'Write the number under the root as a perfect square times a number with no square factor.');
const sqF = [4, 9, 16, 36, 144].map((s) => [d(String(s)), 1008 % s === 0 ? 'yes' : 'no', 1008 % s === 0 ? d(String(1008 / s)) : '-']);
