const sqTable = table(['Perfect square', 'Divides $1008$?', 'Quotient'], sqF, 'Table testing perfect squares against one thousand eight. Four, nine, sixteen, thirty six and one hundred forty four all divide it, leaving two hundred fifty two, one hundred twelve, sixty three, twenty eight and seven. The largest, one hundred forty four, leaves seven, which has no square factor.', 'Use the largest square factor, $144$; the quotient $7$ has no square factor left.');
const likeRows = [[r`\sqrt{18}`, r`\sqrt{50}`], [r`\sqrt{12}`, r`\sqrt{27}`], [r`\sqrt{20}`, r`\sqrt{30}`]];
const likeCells = likeRows.map(([a, b]) => { const x = V(a), y = V(b); const ka = [...x.m.keys()].join(), kb = [...y.m.keys()].join(); const like = ka === kb; return [d(`${a}, ${b}`), d(`${tex(x)}, ${tex(y)}`), like ? 'like surds' : 'unlike surds']; });
must(likeCells.map((c) => c[2]).join() === 'like surds,like surds,unlike surds', 'like cells');
const likeTable = table(['Pair', 'Simplified', 'Kind'], likeCells, 'Table of three pairs. Root eighteen and root fifty simplify to three root two and five root two, like surds. Root twelve and root twenty seven simplify to two root three and three root three, like surds. Root twenty is two root five and root thirty cannot be simplified, so these are unlike surds.', 'Only like surds can be added or subtracted.');
const w2 = chain([r`4\sqrt{20} + 3\sqrt{45} - \sqrt{80} = 8\sqrt{5} + 9\sqrt{5} - 4\sqrt{5} = 13\sqrt{5}`]);
must(w2.eq(V(r`13\sqrt{5}`)), 'w2');
