chain([r`4\sqrt{20} = 8\sqrt{5}`]); chain([r`3\sqrt{45} = 9\sqrt{5}`]); chain([r`\sqrt{80} = 4\sqrt{5}`]); chain([r`(8 + 9 - 4)\sqrt{5} = 13\sqrt{5}`]);
const prRows = [r`\sqrt{6} \times \sqrt{10}`, r`2\sqrt{3} \times 5\sqrt{6}`, r`\dfrac{\sqrt{72}}{\sqrt{8}}`, r`\dfrac{6\sqrt{14}}{3\sqrt{2}}`];
const prVals = [V(prRows[0]), V(prRows[1]), V(prRows[2]), V(prRows[3])];
must(tex(prVals[0]) === '2\\sqrt{15}' && tex(prVals[1]) === '30\\sqrt{2}' && tex(prVals[2]) === '3' && tex(prVals[3]) === '2\\sqrt{7}', 'product table');
const prTable = table(['Expression', 'Working', 'Answer'], [[d(prRows[0]), d(r`\sqrt{60} = \sqrt{4 \times 15}`), d(tex(prVals[0]))], [d(prRows[1]), d(r`10\sqrt{18} = 10 \times 3\sqrt{2}`), d(tex(prVals[1]))], [d(prRows[2]), d(r`\sqrt{\dfrac{72}{8}} = \sqrt{9}`), d(tex(prVals[2]))], [d(prRows[3]), d(r`2\sqrt{\dfrac{14}{2}} = 2\sqrt{7}`), d(tex(prVals[3]))]], 'Table of four products and quotients of surds: root six times root ten is two root fifteen; two root three times five root six is thirty root two; root seventy two over root eight is three; six root fourteen over three root two is two root seven.', 'Multiply coefficients with coefficients and surds with surds; then simplify.');
chain([r`\sqrt{60} = \sqrt{4 \times 15}`]); chain([r`10\sqrt{18} = 10 \times 3\sqrt{2}`]); chain([r`\sqrt{\dfrac{72}{8}} = \sqrt{9}`]); chain([r`2\sqrt{\dfrac{14}{2}} = 2\sqrt{7}`]);
chain([r`\sqrt{6} \times \sqrt{10} = \sqrt{60} = 2\sqrt{15}`]); chain([r`2\sqrt{3} \times 5\sqrt{6} = 10\sqrt{18} = 30\sqrt{2}`]); chain([r`\dfrac{\sqrt{72}}{\sqrt{8}} = \sqrt{9} = 3`]); chain([r`\dfrac{6\sqrt{14}}{3\sqrt{2}} = 2\sqrt{7}`]);
