must(cmpSq.map((x) => x.part()[0]).join() === '63,60,48' && V(cmpItems[0]).value > V(cmpItems[1]).value && V(cmpItems[1]).value > V(cmpItems[2]).value, 'compare');
const cmpTable = table(['Ribbon', 'Under one root', 'Square'], cmpItems.map((s, i) => [d(s), d(`\\sqrt{${cmpSq[i].part()[0]}}`), d(String(cmpSq[i].part()[0]))]), 'Table comparing three ribbon lengths. Three root seven is root sixty three; two root fifteen is root sixty; four root three is root forty eight. The order from longest is three root seven, two root fifteen, four root three.', 'Put every surd under one root sign (or square it) and compare the numbers.');
const conjRows = [[r`3 + \sqrt{5}`, r`3 - \sqrt{5}`], [r`2\sqrt{3} + 1`, r`2\sqrt{3} - 1`], [r`\sqrt{7} - \sqrt{2}`, r`\sqrt{7} + \sqrt{2}`]];
